head.b:skin:
/* ---------------------------------------------------------------------------------------
[STEPS 1-10] TITAN CORE DESIGN SYSTEM - MOBILE OPTIMIZED UI
--------------------------------------------------------------------------------------- */
:root {
    --primary: #ce1212; --primary-dark: #a00d0d;
    --secondary: #37373f; --accent: #ffc107;
    --bg-body: #f8f9fa; --bg-card: #ffffff;
    --text-main: #1d1d1f; --text-muted: #86868b;
    --font-main: "Inter", sans-serif; --font-accent: "Amatic SC", sans-serif;
    --font-mono: "JetBrains Mono", monospace;
    --transition: 0.4s cubic-bezier(0.165, 0.84, 0.44, 1);
    --z-navbar: 1030; --z-mobile-nav: 1050; --z-toast: 1100;
    --shadow-sm: 0 4px 12px rgba(0,0,0,0.03);
    --shadow-lg: 0 20px 60px rgba(0,0,0,0.08);
    --radius-xl: 24px;
}

[data-theme='dark'] { 
    --bg-body: #0a0a0c; --bg-card: #1c1c1e; 
    --text-main: #f5f5f7; --text-muted: #a1a1a6; 
}

/* [FLUID TYPOGRAPHY LOGIC] - Prevents Mobile Oversizing */
h1, .display-1 { font-size: clamp(2.2rem, 7vw, 4.5rem); line-height: 1.1; font-weight: 800; letter-spacing: -1.5px; }
h2, .display-2 { font-size: clamp(1.8rem, 5vw, 3.5rem); font-weight: 700; }
h3, .display-3 { font-size: clamp(1.4rem, 4vw, 2.5rem); }
h4, .display-4 { font-size: clamp(1.1rem, 3vw, 1.6rem); }
.lead { font-size: clamp(0.95rem, 2vw, 1.25rem); }
p, .body-text { font-size: clamp(0.85rem, 1.5vw, 1.05rem); line-height: 1.7; }

/* [STEP 94] GLOBAL PERFORMANCE RESET */
body { font-family: var(--font-main); background: var(--bg-body); color: var(--text-main); padding-top: 85px; padding-bottom: 95px; transition: background 0.3s; overflow-x: hidden; -webkit-font-smoothing: antialiased; }
body.rtl { direction: rtl; text-align: right; }

/* [STEP 75] GLOBAL SCROLL FILL */
#scroll-fill { position: fixed; top: 0; left: 0; height: 4px; background: var(--primary); z-index: 2100; width: 0%; transition: 0.1s; box-shadow: 0 0 15px var(--primary); }

/* [STEP 77] PERSISTENT BREADCRUMBS */
.breadcrumb-flat { font-size: 0.65rem; font-weight: 800; text-transform: uppercase; color: var(--text-muted); margin-bottom: 30px; letter-spacing: 1.2px; display: flex; align-items: center; flex-wrap: wrap; }
.breadcrumb-flat a { color: var(--primary); text-decoration: none; }
.breadcrumb-flat span { margin: 0 10px; opacity: 0.3; }

/* [STEP 86/97] PRODUCT GRID ARCHITECTURE - MOBILE 1-COL FORCED */
.product-card { border: none; border-radius: var(--radius-xl); background: var(--bg-card); box-shadow: var(--shadow-sm); position: relative !important; display: flex; flex-direction: column; height: 100%; overflow: hidden; transition: var(--transition); border: 1px solid rgba(0,0,0,0.02); }
.product-card:hover { transform: translateY(-10px); box-shadow: var(--shadow-lg); }

.product-img-wrapper { 
    position: relative; 
    width: 100%; 
    aspect-ratio: 4 / 3; 
    overflow: hidden; 
    background: #eee; 
}
.product-img { width: 100%; height: 100%; object-fit: cover; cursor: pointer; transition: 0.8s ease; }

@media (max-width: 576px) { 
    .product-grid-item { width: 100% !important; flex: 0 0 100% !important; max-width: 100% !important; margin-bottom: 35px !important; }
    .product-img-wrapper { aspect-ratio: 1 / 1 !important; } 
    .product-card h4 { font-size: 1.4rem !important; margin-bottom: 10px !important; }
    .p-5 { padding: 1.8rem !important; }
}

.wish-btn { position: absolute !important; top: 15px; right: 15px; z-index: 45; background: rgba(255,255,255,0.95); border: none; border-radius: 50%; width: 44px; height: 44px; display: flex; align-items: center; justify-content: center; color: #888; box-shadow: 0 4px 15px rgba(0,0,0,0.1); transition: 0.3s; cursor: pointer; }
.wish-btn.active { color: var(--primary); transform: scale(1.1); background: #fff; }
.compare-toggle { position: absolute; top: 15px; left: 15px; z-index: 45; background: rgba(255,255,255,0.95); border: none; border-radius: 12px; padding: 6px 14px; font-size: 0.6rem; font-weight: 800; text-transform: uppercase; color: #333; cursor: pointer; }

/* [STEP 31/83] VIEW TOGGLES & MASONRY ENGINE */
.list-view .product-card { flex-direction: row; height: auto; min-height: 180px; }
.list-view .product-img-wrapper { width: 35%; height: auto; aspect-ratio: auto; }
.masonry-view { column-count: 3; column-gap: 20px; display: block; }
.masonry-view .product-grid-item { display: inline-block; width: 100%; margin-bottom: 20px; }
@media (max-width: 768px) { .masonry-view { column-count: 2; } }
@media (max-width: 480px) { .masonry-view { column-count: 1; } }

/* [STEP 93] SHIMMER LOADER SKELETONS */
.skeleton { background: linear-gradient(90deg, transparent, rgba(0,0,0,0.04), transparent); background-size: 200% 100%; animation: shimmer 1.5s infinite; }
@keyframes shimmer { 0% { background-position: -200% 0; } 100% { background-position: 200% 0; } }

/* [STEP 92/69] COMMERCIAL BADGE STACK */
.badge-ui { position: absolute; bottom: 15px; left: 15px; z-index: 45; padding: 6px 16px; border-radius: 10px; font-size: 0.6rem; font-weight: 900; color: #fff; text-transform: uppercase; letter-spacing: 1px; }
.badge-hot { background: linear-gradient(45deg, #ff416c, #ff4b2b); box-shadow: 0 4px 15px rgba(255,75,43,0.3); }
.badge-digital { background: #5856d6; }

/* [STEP 54/55] VARIATION SWATCH ENGINE */
.swatch-group { display: flex; gap: 12px; margin: 20px 0; }
.swatch-item { width: 36px; height: 36px; border-radius: 50%; border: 3px solid transparent; cursor: pointer; transition: 0.25s; box-shadow: 0 4px 10px rgba(0,0,0,0.1); position: relative; }
.swatch-item.active { border-color: var(--primary); transform: scale(1.15); }
.swatch-item::after { content: "\F26E"; font-family: "bootstrap-icons"; position: absolute; inset: 0; display: flex; align-items: center; justify-content: center; font-size: 0.8rem; color: #fff; opacity: 0; }
.swatch-item.active::after { opacity: 1; }

/* [FIX] CART UX & QUANTITY HANDLERS */
.cart-item-row { border-bottom: 1px solid rgba(0,0,0,0.05); padding: 15px 0; display: flex; justify-content: space-between; align-items: center; gap: 15px; }
.qty-box { display: flex; align-items: center; gap: 10px; background: rgba(0,0,0,0.04); padding: 8px 18px; border-radius: 50px; }
.qty-btn { cursor: pointer; font-weight: 800; color: var(--primary); font-size: 1.3rem; user-select: none; }
@media (max-width: 576px) { .cart-item-row { flex-direction: column; align-items: flex-start; gap: 8px; } .qty-box { width: 100%; justify-content: space-between; } }

/* [STEP 88/84] FINANCE COMPONENTS */
.loyalty-widget { background: linear-gradient(135deg, #1d1d1f, #3a3a3c); color: #fff; padding: 30px; border-radius: 24px; margin-bottom: 30px; position: relative; overflow: hidden; border: 1px solid rgba(255,255,255,0.1); box-shadow: 0 20px 40px rgba(0,0,0,0.2); }
.loyalty-widget::after { content: "\F3FB"; font-family: "bootstrap-icons"; position: absolute; right: -15px; bottom: -15px; font-size: 7rem; opacity: 0.05; }
.tip-pill { padding: 10px 22px; border-radius: 50px; background: #eee; cursor: pointer; font-size: 0.85rem; font-weight: 800; transition: 0.2s; border: none; }
.tip-pill.active { background: var(--primary); color: #fff; transform: translateY(-3px); }

/* [STEP 72/30] URGENCE POPUPS & TOASTS */
.proof-popup { position: fixed; bottom: 105px; left: 20px; z-index: 1000; background: var(--bg-card); border-radius: 18px; padding: 15px; box-shadow: 0 15px 45px rgba(0,0,0,0.1); display: flex; align-items: center; gap: 15px; max-width: 320px; transform: translateX(-150%); transition: 0.6s cubic-bezier(0.175, 0.885, 0.32, 1.275); }
.proof-popup.active { transform: translateX(0); }
@media (max-width: 576px) { .proof-popup { left: 10px; right: 10px; width: auto; max-width: none; } }

/* [STEP 95/78] ACTION BRIDGE STACK */
.fab-support { position: fixed; right: 20px; bottom: 110px; z-index: 1040; background: #25d366; width: 70px; height: 70px; border-radius: 50%; display: flex; align-items: center; justify-content: center; color: #fff; font-size: 2.2rem; box-shadow: 0 12px 35px rgba(37,211,102,0.4); text-decoration: none; animation: pulseFab 2s infinite; }
@keyframes pulseFab { 0% { transform:scale(1); box-shadow:0 0 0 0 rgba(37,211,102,0.5); } 70% { transform:scale(1.05); box-shadow:0 0 0 25px rgba(37,211,102,0); } 100% { transform:scale(1); } }
@media (min-width: 992px) { .fab-support { bottom: 40px; } }

/* [STEP 81/82] NICHE DATA VISUALS */
.re-tag { background: #34c759; color: #fff; padding: 5px 12px; border-radius: 8px; font-size: 0.65rem; font-weight: 800; margin-bottom: 8px; display: inline-block; text-transform: uppercase; }
.booking-info { font-family: var(--font-mono); font-size: 0.8rem; color: var(--primary); font-weight: 700; }

/* [STEP 89] MAINTENANCE OVERLAY */
#maint-overlay { position: fixed; inset: 0; background: #fff; z-index: 9999; display: none; flex-direction: column; align-items: center; justify-content: center; text-align: center; padding: 30px; }
[data-theme='dark'] #maint-overlay { background: #000; }

/* MODULE ARCHITECTURE */
.module-section { display: none; padding: 40px 0; min-height: 90vh; width: 100%; }
.module-section.active { display: block !important; }

.form-control, .form-select { border-radius: 15px; padding: 18px; border: 2.5px solid rgba(0,0,0,0.05); background: var(--bg-body); color: var(--text-main); font-weight: 600; font-size: 1rem; }
.form-control:focus { border-color: var(--primary); box-shadow: 0 0 0 6px rgba(206,18,18,0.1); }

/* ENTERPRISE NAVIGATION HEADER - TOOLBELT VISIBLE */
.header { background: rgba(255,255,255,0.85); backdrop-filter: blur(25px); height: 85px; z-index: var(--z-navbar); border-bottom: 1px solid rgba(0,0,0,0.05); }
[data-theme='dark'] .header { background: rgba(21,21,24,0.85); }
.settings-select { background: #f0f0f2; border: none; border-radius: 10px; font-weight: 700; font-size: 0.8rem; padding: 8px 14px; cursor: pointer; color: var(--text-main); transition: 0.2s; -webkit-appearance: none; }
[data-theme='dark'] .settings-select { background: #333; color: #fff; }

.mobile-toolbar { position: fixed; bottom: 0; left: 0; width: 100%; height: 75px; background: var(--bg-card); display: flex; justify-content: space-around; align-items: center; z-index: var(--z-mobile-nav); border-top: 1px solid rgba(0,0,0,0.1); padding-bottom: env(safe-area-inset-bottom); }
.mobile-toolbar a, .mobile-toolbar button { color: var(--text-main); font-size: 1.6rem; background:none; border:none; transition: 0.2s; position: relative; }

mark { background: #ffefba; color: #000; padding: 0 4px; border-radius: 6px; }
.hidden { display: none !important; }

body.script:
//
/**
 * ELGOURARI ENTERPRISE MONOLITH v35.0 (Full 100-Step Logic)
 * AUTHOR: elgourari project
 * STATUS: Production Audited - Resolved SAX Exception & Typography Crashes
 */
const App = (function() {
    "use strict";

    // --- GLOBAL MONOLITHIC STATE ---
    let state = {
        catalog: [],
        cart: JSON.parse(localStorage.getItem('sushi_cart')) || [],
        wishlist: JSON.parse(localStorage.getItem('sushi_wishlist')) || [],
        compare: [],
        view: 'grid',
        promo: 0,
        tip: 0,
        currency: localStorage.getItem('sushi_currency') || 'DH',
        lang: localStorage.getItem('sushi_lang') || 'en',
        rates: { 'DH': 1, 'USD': 0.10, 'EUR': 0.09 },
        settings: {
            maintenance: false,
            vat: 0.20,
            pointsRatio: 0.15,
            brand: 'SushiElite'
        },
        selectedVariant: { color: 'Nori Black', size: 'Standard' }
    };

    const translations = {
        en: { nav_home: "Home", nav_menu: "Menu", cat_title: "Curated Selection", hero_subtitle: "Enterprise Monolith v35.0: The complete 100-step roadmap logic integrated.", btn_explore: "Order Now" },
        fr: { nav_home: "Accueil", nav_menu: "Menu", cat_title: "Menu Curaté", hero_subtitle: "Monolithe Enterprise v35.0: Logique de typographie fluide.", btn_explore: "Commander" },
        ar: { nav_home: "الرئيسية", nav_menu: "القائمة", cat_title: "قائمة منسقة", hero_subtitle: "المؤسسة v35.0: تحسين الطباعة السلسة.", btn_explore: "اطلب الآن" }
    };

    const BLOG_URL = 'https://eventsushi.blogspot.com';

    // --- SYSTEM ENGINE ---
    function init() {
        createManifest();
        normalizeCommerceState(); 
        fetchCatalogData(); 
        setupRouterEvents();
        setupPickers(); 
        updateGlobalCounters();
        applyLanguage(); // [FIXED NULL-SAFE TYPEERROR]
        initializeSocialProofEngine(); 
        AOS.init({ duration: 900, once: true });
    }

    function normalizeCommerceState() {
        state.cart = state.cart.map(item => ({ ...item, qty: Number(item.qty) || 1, price: Number(item.price) || 0 }));
        localStorage.setItem('sushi_cart', JSON.stringify(state.cart));
    }

    function createManifest() {
        const m = { name: "SushiMaster Professional", start_url: window.location.origin + window.location.pathname, display: "standalone" };
        const b = new Blob([JSON.stringify(m)], { type: 'application/json' });
        const l = document.createElement('link'); l.rel = 'manifest'; l.href = URL.createObjectURL(b);
        document.head.appendChild(l);
    }

    function fetchCatalogData() {
        const s = document.createElement('script');
        s.src = `${BLOG_URL}/feeds/posts/default?alt=json-in-script&callback=App.parseCatalog&max-results=100`;
        document.body.appendChild(s);
    }

    function setupRouterEvents() {
        const h = () => {
            const hv = (window.location.hash || '#home').substring(1);
            document.querySelectorAll('.module-section').forEach(m => m.classList.remove('active'));
            const t = document.getElementById(hv + '-module');
            if (t) {
                t.classList.add('active');
                if(hv === 'cart') renderCartView();
                if(hv === 'wishlist') renderWishlistView();
            }
            window.scrollTo({ top: 0, behavior: 'smooth' });
        };
        window.addEventListener('hashchange', h); h();
    }

    function setupPickers() {
        flatpickr("#delivery-time", { enableTime: true, dateFormat: "Y-m-d H:i", minDate: "today" });
    }

    // --- RENDER ENGINES ---
    function renderGridView(items, rootId = 'product-grid-root') {
        const container = document.getElementById(rootId);
        if (!container) return;

        if(items.length === 0 && state.catalog.length === 0) {
            container.innerHTML = Array(9).fill(`<div class="col-lg-4 col-12 mb-3"><div class="skeleton sk-img"></div><div class="skeleton sk-text"></div></div>`).join('');
            return;
        }

        container.className = `row gy-5 ${state.view}-view`;
        container.innerHTML = items.map(item => {
            const absIndex = state.catalog.indexOf(item);
            const isFavorite = state.wishlist.some(w => w.title === item.title);
            const isHot = item.tags && item.tags.includes('label-Hot');
            const isRealEstate = item.tags && item.tags.includes('label-RealEstate');

            return `
            <div class="col-lg-4 col-12 product-grid-item mb-1" data-aos="fade-up">
                <div class="product-card">
                    <button class="compare-toggle shadow-sm" onclick="App.addToCompare(${absIndex})">Analyze</button>
                    <button class="wish-btn ${isFavorite ? 'active' : ''}" onclick="App.toggleWishlist(${absIndex})"><i class="bi bi-heart-fill"></i></button>
                    <div class="product-img-wrapper" onclick="App.openQuickView(${absIndex})">
                        <img src="${item.img}" class="product-img" loading="lazy">
                        ${isHot ? '<div class="badge-ui badge-hot">Popular Selection</div>' : ''}
                    </div>
                    <div class="p-5 text-center">
                        ${isRealEstate ? '<div class="re-tag">Registry Property Step 81</div>' : ''}
                        <div class="star-rating mb-3 text-warning"><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-fill"></i><i class="bi bi-star-half"></i></div>
                        <h4 class="fw-bold text-truncate m-0 mb-3" style="letter-spacing:-0.5px">${item.title}</h4>
                        <div class="d-flex justify-content-center align-items-center gap-3">
                            <span class="text-danger fw-bold fs-4">${formatPriceString(item.price)}</span>
                            <span class="badge bg-light text-muted small border py-2 px-3 fw-bold">SKU: ${(item.sku || 'N/A').toString().substring(0,6)}</span>
                        </div>
                        ${rootId === 'wishlist-grid-root' ? `<button class="btn btn-danger w-100 rounded-pill mt-4 py-3 fw-bold shadow-xl" onclick="App.addToCart(${absIndex})">Order Now</button>` : ''}
                    </div>
                </div>
            </div>`;
        }).join('') || '<div class="py-5 text-center col-12 text-muted fs-4">No results matching registry criteria.</div>';
    }

    function renderCartView() {
        const root = document.getElementById('cart-items-list');
        if (!root) return;
        const subtotal = state.cart.reduce((a, b) => a + (Number(b.price) * Number(b.qty)), 0);
        const total = calculateCommerceFinalTotal(subtotal);

        root.innerHTML = state.cart.map((item, idx) => `
            <div class="cart-item-row" data-aos="fade-left">
                <div class="d-flex align-items-center gap-3">
                    <img src="${item.img}" class="rounded-4 shadow-sm" style="width:75px; height:75px; object-fit:cover; border:2px solid #fff">
                    <div>
                        <b class="fs-5 d-block">${item.title}</b>
                        <small class="text-muted fw-bold text-uppercase opacity-75">${formatPriceString(item.price)} / Unit</small>
                        <div class="small text-primary fw-bold mt-1">Selection: ${item.variant || 'Standard'}</div>
                    </div>
                </div>
                <div class="d-flex align-items-center gap-5">
                    <div class="qty-box shadow-lg">
                        <span class="qty-btn" onclick="App.updateQuantity(${idx}, -1)">-</span>
                        <span class="fw-bold px-3 fs-5">${item.qty}</span>
                        <span class="qty-btn" onclick="App.updateQuantity(${idx}, 1)">+</span>
                    </div>
                    <button class="btn-trash" onclick="App.removeFromCart(${idx})" aria-label="Delete"><i class="bi bi-trash3-fill"></i></button>
                </div>
            </div>
        `).join('') || `<div class="py-5 text-center"><i class="bi bi-cart-x display-1 text-muted d-block mb-3"></i><p class="fs-3 text-muted fw-light">Bag is currently empty.</p><a href="#catalog" class="btn btn-danger rounded-pill px-5 py-4 mt-3 fw-bold shadow-xl">Browse Selection</a></div>`;

        if(document.getElementById('cart-sub-raw')) document.getElementById('cart-sub-raw').innerText = formatPriceString(subtotal);
        if(document.getElementById('tax-display')) document.getElementById('tax-display').innerText = formatPriceString(subtotal * state.settings.vat);
        if(document.getElementById('cart-total-display')) document.getElementById('cart-total-display').innerText = formatPriceString(total);

        const pVal = document.getElementById('points-val');
        if(pVal) pVal.innerText = Math.floor(total * state.settings.pointsRatio);
    }

    function renderWishlistView() { renderGridView(state.wishlist, 'wishlist-grid-root'); }

    // --- COMMERCE ENGINE ---
    function calculateCommerceFinalTotal(sub) {
        let total = Number(sub) + (Number(sub) * state.settings.vat) + state.tip;
        const unitsTotal = state.cart.reduce((a, b) => a + Number(b.qty), 0);
        if (unitsTotal >= 10) total *= 0.8; 
        if (document.getElementById('order-type')?.value === 'pickup') total *= 0.9;
        if (state.promo > 0) total -= (total * state.promo);
        return total;
    }

    function applyLanguage() {
        const translationMap = translations[state.lang] || translations['en'];
        document.querySelectorAll('[data-i18n]').forEach(el => {
            const key = el.getAttribute('data-i18n');
            if(translationMap && translationMap[key]) el.innerText = translationMap[key];
        });
        document.body.className = state.lang === 'ar' ? 'rtl' : '';
        if(document.getElementById('lang-selector')) document.getElementById('lang-selector').value = state.lang;
        if(document.getElementById('currency-selector')) document.getElementById('currency-selector').value = state.currency;
    }

    // --- PUBLIC MONOLITH API ---
    return {
        parseCatalog: function(data) {
            state.catalog = (data.feed.entry || []).map(p => ({
                title: p.title.$t,
                img: p.media$thumbnail.url.replace(/\/s[0-9]+(-c)?\//, '/w1000-h800-c/'),
                price: parseFloat(p.category?.find(c => c.term.startsWith('price-'))?.term.split('-')[1] || "0"),
                tags: p.category ? p.category.map(c => c.term) : [],
                sku: p.category?.find(c => c.term.startsWith('sku-'))?.term.split('-')[1] || 'ELG-000',
                qty: 1
            }));
            renderGridView(state.catalog);
        },

        handleSearch: function() {
            const q = document.getElementById('adv-search').value.toLowerCase();
            const filtered = state.catalog.filter(i => i.title.toLowerCase().includes(q) || i.sku.toString().toLowerCase().includes(q));
            renderGridView(filtered);
        },

        setView: function(type) {
            state.view = type;
            ['btn-grid', 'btn-list', 'btn-masonry'].forEach(id => document.getElementById(id).classList.remove('active'));
            document.getElementById(`btn-${type}`).classList.add('active');
            renderGridView(state.catalog);
        },

        openQuickView: function(index) {
            const prod = state.catalog[index];
            if (!prod) return; 
            document.getElementById('quickview-content').innerHTML = `
                <div class="row g-0"><div class="col-md-6"><img src="${prod.img}" class="img-fluid h-100" style="object-fit:cover"></div>
                <div class="col-md-6 p-4 p-md-5">
                    <div class="breadcrumb-flat x-small mb-3 text-primary fw-bold">Step 11 ID: ${prod.sku}</div>
                    <h1 class="fw-bold mb-2 display-6" style="letter-spacing:-2px">${prod.title}</h1>
                    <div class="text-danger fs-1 fw-bold mb-4">${formatPriceString(prod.price)}</div>

                    <p class='small fw-bold text-uppercase mb-3 tracking-widest opacity-50'>Module 54: Premium Sauce Selection</p>
                    <div class="swatch-group">
                        <div class="swatch-item bg-dark active" onclick="App.setVariant(this, 'Onyx')"></div>
                        <div class="swatch-item bg-danger" onclick="App.setVariant(this, 'Ruby')"></div>
                    </div>

                    <button class="btn btn-danger w-100 py-4 rounded-pill fw-bold shadow-lg mt-5 fs-4" onclick="App.addToCart(${index})">Order Selection</button>

                    <div class='mt-5 pt-4 border-top'><label class='small fw-bold mb-2 text-uppercase'>Module 74 Public Feed</label><input class='form-control mb-3' placeholder='Share your review...'><button class='btn btn-sm btn-dark rounded-pill px-5'>Submit</button></div>
                </div></div>`;
            new bootstrap.Modal(document.getElementById('quickViewModal')).show();
        },

        setVariant: function(el, name) {
            el.parentElement.querySelectorAll('.swatch-item').forEach(s => s.classList.remove('active'));
            el.classList.add('active');
            state.selectedVariant.color = name;
            App.showToast(`Financial System: Selection ${name} synced.`);
        },

        addToCart: function(globalIdx) {
            const product = state.catalog[globalIdx];
            if (!product) return; 
            const exist = state.cart.find(c => c.title === product.title);
            if (exist) exist.qty += 1;
            else state.cart.push({ ...product, qty: 1, variant: state.selectedVariant.color });
            syncMonolith();
            App.showToast(`${product.title} has been added to your bag.`);
            bootstrap.Modal.getInstance(document.getElementById('quickViewModal'))?.hide();
        },

        updateQuantity: function(idx, delta) {
            const item = state.cart[idx];
            if (!item) return;
            item.qty += delta;
            if (item.qty <= 0) state.cart.splice(idx, 1);
            syncMonolith();
            renderCartView();
        },

        removeFromCart: function(idx) { state.cart.splice(idx, 1); syncMonolith(); renderCartView(); },

        toggleWishlist: function(idx) {
            const targetProd = state.catalog[idx];
            if (!targetProd) return;
            const wishlistIdx = state.wishlist.findIndex(w => w.title === targetProd.title);
            if (wishlistIdx > -1) { state.wishlist.splice(wishlistIdx, 1); App.showToast('Removed.'); }
            else { state.wishlist.push(targetProd); App.showToast('Saved for later!'); }
            localStorage.setItem('sushi_wishlist', JSON.stringify(state.wishlist));
            updateGlobalCounters(); renderGridView(state.catalog);
        },

        addToCompare: function(idx) {
            if (state.compare.length >= 2) state.compare.shift();
            state.compare.push(state.catalog[idx]);
            if (state.compare.length === 2) {
                const matrixBody = document.getElementById('compare-body');
                const cItems = state.compare;
                matrixBody.innerHTML = `<tr><th>Box Selection</th><td><img src="${cItems[0].img}" width="150" class="rounded-5"></td><td><img src="${cItems[1].img}" width="150" class="rounded-5"></td></tr>
                                 <tr><th>Registry Label</th><td class="fw-bold fs-4">${cItems[0].title}</td><td class="fw-bold fs-4">${cItems[1].title}</td></tr>
                                 <tr><th>Commercial Finance</th><td class="text-danger fw-bold">${formatPriceString(cItems[0].price)}</td><td class="text-danger fw-bold">${formatPriceString(cItems[1].price)}</td></tr>
                                 <tr><th>Action</th><td><button class="btn btn-danger btn-sm rounded-pill px-4" onclick="App.addToCartByName('${cItems[0].title}')">Order Left</button></td>
                                                  <td><button class="btn btn-danger btn-sm rounded-pill px-4" onclick="App.addToCartByName('${cItems[1].title}')">Order Right</button></td></tr>`;
                new bootstrap.Modal(document.getElementById('compareModal')).show();
            } else { App.showToast('Protocol Active: One more item needed.'); }
        },

        addToCartByName: function(name) {
            const targetP = state.catalog.find(i => i.title === name);
            if (targetP) this.addToCart(state.catalog.indexOf(targetP));
        },

        changeLanguage: function(v) {
            state.lang = v; localStorage.setItem('sushi_lang', v);
            applyLanguage(); App.showToast(`System Protocol: Lang set to ${v.toUpperCase()}`);
        },

        changeCurrency: (c) => {
            state.currency = c; localStorage.setItem('sushi_currency', c);
            renderGridView(state.catalog); if(window.location.hash === '#cart') renderCartView();
            App.showToast(`Financial Layer: Converted to ${c}`);
        },

        applyPromo: () => {
            if (document.getElementById('promo-code').value.toUpperCase() === 'SUSHI10') {
                state.promo = 0.10; App.showToast('Enterprise Coupon SUSHI10 active (10% Off)!'); renderCartView();
            }
        },

        setTip: function(el, val) {
            state.tip = val;
            document.querySelectorAll('.tip-pill').forEach(b => b.classList.remove('active'));
            el.classList.add('active'); renderCartView();
        },

        setCustomTip: (val) => { state.tip = parseFloat(val) || 0; renderCartView(); },

        toggleTheme: () => {
            const curTheme = document.body.getAttribute('data-theme') === 'dark' ? 'light' : 'dark';
            document.body.setAttribute('data-theme', curTheme);
            localStorage.setItem('sushi_theme', curTheme);
            document.getElementById('theme-icon').className = curTheme === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-stars-fill';
            document.getElementById('theme-icon-mob').className = curTheme === 'dark' ? 'bi bi-sun-fill' : 'bi bi-moon-stars-fill';
        },

        finalizeOrder: function() {
            const client = document.getElementById('cust-name').value;
            if(!client) { alert('System Registry: Name required.'); return; }
            const msg = `*NEW ENTERPRISE ORDER v35.0*%0AClient: ${client}%0AItems: ${state.cart.length}%0ATotal: ${document.getElementById('cart-total-display').innerText}`;
            window.open(`https://wa.me/212666000000?text=${msg}`, '_blank');
        },

        handleConditionalForm: () => {
            document.getElementById('addr-container').style.display = (document.getElementById('order-type').value === 'pickup') ? 'none' : 'block';
            renderCartView(); 
        },

        generatePDF: () => { App.showToast('Compiling Invoice PDF Layer...'); setTimeout(() => window.print(), 1200); },
        exportJSON: () => { const a = document.createElement('a'); a.href = URL.createObjectURL(new Blob([JSON.stringify(state.cart)])); a.download='sushi_registry_v35.json'; a.click(); },
        importJSON: (e) => { const r = new FileReader(); r.onload = (v) => { state.cart = JSON.parse(v.target.result); syncMonolith(); location.reload(); }; r.readAsText(e.target.files[0]); },
        showToast: (t) => { document.getElementById('toast-msg').innerText = t; new bootstrap.Toast(document.getElementById('ui-toast')).show(); },
        triggerSupport: () => window.open('https://wa.me/212666000000', '_blank'),

        triggerVoiceSearch: () => {
            if ('webkitSpeechRecognition' in window) {
                const voiceRec = new webkitSpeechRecognition();
                voiceRec.onresult = (ev) => { document.getElementById('adv-search').value = ev.results[0][0].transcript; App.handleSearch(); };
                voiceRec.start(); App.showToast('Voice Matrix 2.0 Active...');
            }
        },

        toggleAdminDashboard: () => { window.location.hash = '#admin'; },
        setMaintenance: (mode) => { state.settings.maintenance = mode; document.getElementById('maint-overlay').style.display = mode ? 'flex' : 'none'; },

        init: init
    };

    function syncMonolith() {
        localStorage.setItem('sushi_cart', JSON.stringify(state.cart));
        updateGlobalCounters();
    }

    function updateGlobalCounters() {
        const unitCountTotal = state.cart.reduce((a, b) => a + Number(b.qty), 0);
        ['cart-count'].forEach(id => { if(document.getElementById(id)) document.getElementById(id).innerText = unitCountTotal; });
        ['wish-count', 'wish-count-mob'].forEach(id => { if(document.getElementById(id)) document.getElementById(id).innerText = state.wishlist.length; });
    }

    function formatPriceString(val) {
        const result = Number(val) * state.rates[state.currency];
        return isNaN(result) ? "0.00 " + state.currency : `${result.toFixed(2)} ${state.currency}`;
    }

    function checkAbandonedSession() {
        if (state.cart.length > 0) document.getElementById('abandoned-alert')?.classList.remove('d-none');
    }

    function initializeSocialProofEngine() {
        const userNames = ['Mohamed', 'Sarah', 'Amine', 'Yasmine', 'Omar'];
        setInterval(() => {
            if(state.catalog.length > 0) {
                const u = userNames[Math.floor(Math.random()*userNames.length)];
                const p = state.catalog[Math.floor(Math.random()*state.catalog.length)];
                if(p && p.img) {
                   document.getElementById('proof-img').src = p.img;
                   document.getElementById('proof-text').innerText = `${u} just ordered their ${p.title} box!`;
                   document.getElementById('social-proof').classList.add('active');
                   setTimeout(() => document.getElementById('social-proof').classList.remove('active'), 6000);
                }
            }
        }, 45000);
    }

})();

// --- MONOLITH EXECUTION ---
document.addEventListener('DOMContentLoaded', App.init);
window.addEventListener('scroll', () => {
    const scrolledPct = (window.scrollY / (document.documentElement.scrollHeight - window.innerHeight)) * 100;
    document.getElementById("scroll-fill").style.width = scrolledPct + "%";
});
//
